-- ============================================================
-- SEED EXT 3: Módulo 09 — Conditional Type 1 (ex 137-215)
-- Novos tópicos: Type 0 vs Type 1, modals no resultado,
-- condições implícitas, academic predictions, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'conditional-1';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo conditional-1 não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: Type 0 vs Type 1 avançado
  (cid,31,137,'multiple_choice','What is the key difference between Type 0 and Type 1 conditionals?','Type 0 expresses universal truths/facts; Type 1 expresses a specific probable future condition.','["Type 0 uses will; Type 1 does not","Type 0 expresses universal truths/facts; Type 1 expresses a specific probable future condition.","Type 0 is for the past; Type 1 is for the present","They are identical"]','Type 0: "If water reaches 100°C, it boils." Type 1: "If you study, you will pass."','medium'),
  (cid,31,138,'gap_fill','If the temperature _____ (drop) below 0°C, water _____ (freeze). (Type 0 — scientific law)','drops / freezes',NULL,'Type 0: present simple in both clauses. States a scientific fact.','easy'),
  (cid,31,139,'gap_fill','If the temperature _____ (drop) below zero tonight, the pipes in the building _____ (freeze). (Type 1 — specific prediction)','drops / will freeze',NULL,'Type 1: present simple if-clause + will + base verb. Specific condition tonight.','easy'),
  (cid,31,140,'multiple_choice','Which is a Type 0 conditional?','When/If a cell lacks oxygen, it undergoes anaerobic respiration.','["If the cell lacks oxygen today, it will undergo anaerobic respiration.","When/If a cell lacks oxygen, it undergoes anaerobic respiration.","If the cell lacked oxygen, it would undergo anaerobic respiration.","If the cell had lacked oxygen, it would have undergone anaerobic respiration."]','Type 0: general/scientific truth. Present simple + present simple. "When" interchangeable with "if."','easy'),
  (cid,31,141,'gap_fill','In academic writing, Type 0 conditionals are used to describe _____ (general / scientific) truths or established facts.','general / scientific / universal',NULL,'Type 0 = scientific generalizations and universal truths (always true).','easy'),

  -- BLOCK 32: modais no resultado — can, may, might, should
  (cid,32,142,'gap_fill','If you submit your application before the deadline, you _____ (may + consider/passive) for the scholarship.','may be considered',NULL,'"May + be + past participle" = modal + passive in Type 1 result clause.','medium'),
  (cid,32,143,'multiple_choice','Which Type 1 result clause uses a modal MOST appropriately for uncertainty?','If the therapy continues for six weeks, the patient might show significant improvement.','["If the therapy continues for six weeks, the patient shows significant improvement (Type 0 — too certain).","If the therapy continues for six weeks, the patient will show significant improvement (too certain).","If the therapy continues for six weeks, the patient might show significant improvement.","If the therapy continues for six weeks, the patient would show significant improvement (Type 2 — wrong tense)."]','"Might" in the result clause = possible but uncertain outcome.','hard'),
  (cid,32,144,'gap_fill','If the government _____ (invest) in renewable energy now, it _____ (could/reduce) carbon emissions by 40% within a decade.','invests / could reduce',NULL,'"Could" in result clause = achievable outcome (with effort).','medium'),
  (cid,32,145,'multiple_choice','What is the difference between "will," "can," and "may" in Type 1 result clauses?','"Will" = certain; "can" = possible/ability; "may/might" = uncertain/less probable.','["They are identical in meaning","''Will'' = certain; ''can'' = possible/ability; ''may/might'' = uncertain/less probable.","Can is more formal than will","May is more certain than will"]','"Will" (high certainty) > "can/could" (ability/possibility) > "may/might" (less certain).','hard'),
  (cid,32,146,'gap_fill','If you _____ (not/take) the preliminary exam, you _____ (cannot/proceed) to the advanced level.','do not take / cannot proceed / will not be able to proceed',NULL,'"Cannot" or "will not be able to" = ability-denial in Type 1 result clause.','medium'),

  -- BLOCK 33: condições implícitas (sem if)
  (cid,33,147,'gap_fill','_____ (Study) consistently and you will improve your score significantly.','Study / If you study',NULL,'Imperative + and = conditional: "Do X and Y will happen."','medium'),
  (cid,33,148,'multiple_choice','Which sentence contains an IMPLICIT conditional (no "if")?','Miss the submission deadline, and your application will be automatically disqualified.','["If you miss the submission deadline, your application will be disqualified.","Miss the submission deadline, and your application will be automatically disqualified.","Unless you submit on time, your application is disqualified.","Submit on time or your application is disqualified (also implicit — or = if not)."]','Imperative + and = implicit Type 1 conditional.','medium'),
  (cid,33,149,'gap_fill','_____ (Fail) to declare all sources of funding, and the grant _____ (cancel/passive) immediately.','Fail / will be cancelled',NULL,'Implicit conditional: imperative + and + result clause (will + passive).','hard'),
  (cid,33,150,'multiple_choice','What is the difference between "X or Y will happen" and "X and Y will happen" as implicit conditionals?','"X and Y" = do X → Y will follow (positive condition). "X or Y" = if NOT X → Y will happen (negative condition).','["They are identical","''X and Y'' = do X → Y will follow (positive condition). ''X or Y'' = if NOT X → Y will happen.","Or implies certainty; and implies doubt","And is more formal"]','Imperative + AND = positive condition. Imperative + OR = negative condition (threat).','hard'),
  (cid,33,151,'gap_fill','Submit your thesis by June 1st _____ (or) you will not be eligible to graduate this semester.','or',NULL,'"Submit X or Y will happen" = implicit negative conditional: if you don''t submit, Y.','medium'),

  -- BLOCK 34: academic predictions e forecasting
  (cid,34,152,'gap_fill','If current emission trends _____ (continue), global temperatures _____ (likely/exceed) 2°C above pre-industrial levels by 2050.','continue / will likely exceed / are likely to exceed',NULL,'Academic Type 1 with hedging adverb: "will likely" or "are likely to."','medium'),
  (cid,34,153,'multiple_choice','Which sentence is most appropriate for an academic forecast?','If demographic trends continue as projected, the global population may reach ten billion by 2050.','["If demographic trends continue as projected, the global population reaches ten billion by 2050 (Type 0 — too certain for a forecast).","If demographic trends continue as projected, the global population will reach ten billion by 2050 (less hedged).","If demographic trends continue as projected, the global population may reach ten billion by 2050.","If demographic trends continue as projected, the global population would reach ten billion by 2050 (Type 2 — wrong)."]','"May" in academic forecast = hedged prediction. Appropriately tentative.','hard'),
  (cid,34,154,'gap_fill','If biodiversity _____ (continue/decline) at the current rate, ecosystems _____ (face/be projected to) collapse within decades.','continues to decline / will face / are projected to face',NULL,'Academic forecast: present simple + will/be projected to in result clause.','hard'),
  (cid,34,155,'multiple_choice','In academic writing, Type 1 conditionals in forecasting often use which alternative to "will"?','Is/are projected to / is/are expected to / is/are likely to.','["Would","Is/are projected to / is/are expected to / is/are likely to.","Had","Should"]','Academic hedging: "is projected to" / "is expected to" = more tentative than "will."','medium'),

  -- BLOCK 35: TOEFL Reading
  (cid,35,156,'multiple_choice','[TOEFL Reading] "If deforestation rates do not slow significantly, the Amazon basin may lose over 25% of its tree cover within thirty years." This sentence is:','A Type 1 conditional with a hedged result clause (may).','["A Type 2 conditional","A Type 0 scientific law","A Type 1 conditional with a hedged result clause (may).","A Type 3 conditional about the past"]','Type 1: present simple if-clause + may (hedged) result.','easy'),
  (cid,35,157,'gap_fill','[TOEFL Reading] "If antibiotics _____ (continue) to be overused, resistant bacteria _____ (make/passive) many current treatments obsolete." Best form?','continue / will make / could make / may be made',NULL,'Type 1 academic prediction: present simple + will/may/could.','medium'),
  (cid,35,158,'multiple_choice','[TOEFL Reading] "Provided that the infrastructure investment is made in the next decade, economic growth rates can be expected to rise." "Provided that" means:','On the condition that — equivalent to "if only if."','["Despite the fact that","As a result of","On the condition that — equivalent to ''only if.''","Even though"]','"Provided that" = conditional conjunction (= "if and only if").','easy'),
  (cid,35,159,'gap_fill','[TOEFL Reading] "_____ (Should) the clinical trials produce positive results, regulatory approval could follow within two years." Identify this conditional form.','Should (= inverted Type 1 formal conditional)',NULL,'"Should + subject + base verb" = formal inverted Type 1.','hard'),

  -- BLOCK 36: TOEFL Speaking
  (cid,36,160,'production','[TOEFL Speaking — 45s] A reading predicts that if governments invest in public transportation, air pollution and traffic congestion will decrease. Discuss the conditions and results. Use: Type 1, should (inverted), may/might, provided that.','',NULL,'The reading argues convincingly that public investment in transportation infrastructure offers multiple co-benefits. If governments prioritize high-quality metro systems and bus networks, private car usage will decrease proportionally. Should these investments be paired with pricing mechanisms that make driving more expensive in urban centers, the shift away from cars could be dramatic. Provided that the public transportation options are genuinely convenient, reliable, and affordable, commuters may well abandon cars voluntarily. Might there be initial resistance? Almost certainly — but the long-term air quality and quality-of-life gains would likely outweigh short-term political challenges.','hard'),
  (cid,36,161,'production','[TOEFL Speaking — 45s] A friend is considering dropping out of university due to financial pressure. Give advice using Type 1 conditionals, implicit conditionals (imperative + and/or), and modal variations (can, may, might).','',NULL,'Before making such an important decision, consider the long-term consequences. If you leave now without completing your degree, your earning potential over a lifetime may be significantly lower. Speak to the financial aid office, and you might discover options — scholarships, emergency funds, or flexible payment plans — that you were not aware of. Take a leave of absence rather than dropping out entirely, or you could close doors permanently. If you explain your situation honestly to your academic advisor, they can often arrange accommodations that make continuing possible. Leaving is a decision that will be hard to reverse.','hard'),

  -- BLOCK 37: TOEFL Writing
  (cid,37,162,'production','[TOEFL Writing — 150 words] Write an academic paragraph predicting the effects of climate change on agriculture. Use: Type 1 (×3), Type 0 (×1), may/might (×2), is projected to (×1), implicit conditional (imperative + and, ×1).','',NULL,'Agriculture is acutely vulnerable to climate change, and current trajectories suggest severe disruption to global food systems. If average temperatures rise by 2°C, crop yields for staple foods such as wheat and maize are projected to decline by as much as 25% in tropical and subtropical regions. If drought frequency increases, as climate models predict, water-intensive crops may become non-viable across large areas of sub-Saharan Africa and South Asia. Conversely, when growing seasons lengthen in northern latitudes — as they invariably do when temperatures rise — some previously cold regions might become productive agricultural land. Address these challenges now, and future generations will have far more tools at their disposal than if the transition is delayed for decades. Type 1 logic therefore compels early action: the sooner the conditions are created for adaptation, the less severe the ultimate consequences will be.','hard'),
  (cid,37,163,'production','[TOEFL Writing — Error Correction] Fix conditional Type 1 errors: "If it will rain tomorrow, we cancel the outdoor event. If water boils, it will turn into steam (Type 0 error). If you study hard, you can passing the exam. Submit your application, or you will considered for the grant. Should you will need help, contact the support team."','',NULL,'will rain → rains (Type 1 if-clause: present simple, not will); will turn → turns (Type 0: both clauses present simple — will is for Type 1, not Type 0); can passing → can pass (modal + base verb, not -ing); you will considered → you will be considered (need passive: will be considered); Should you will need → Should you need (inverted conditional: Should + subject + base verb, no ''will'').','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
